-- Generated from San Luis Obispo OpenStreetMap extracts. Run after schema.sql.
-- Previous Berkeley seed rows are hidden rather than deleted, preserving reviews.
alter table public.places add column if not exists latitude double precision;
alter table public.places add column if not exists longitude double precision;
alter table public.places add column if not exists source_url text;
alter table public.places add column if not exists is_active boolean not null default true;
alter table public.places alter column price_level drop not null;
alter table public.places alter column hours drop not null;

update public.places set is_active = false
where id in ('a1000000-0000-4000-8000-000000000001', 'a1000000-0000-4000-8000-000000000002', 'a1000000-0000-4000-8000-000000000003', 'a1000000-0000-4000-8000-000000000004', 'a1000000-0000-4000-8000-000000000005', 'a1000000-0000-4000-8000-000000000006', 'a1000000-0000-4000-8000-000000000007', 'a1000000-0000-4000-8000-000000000008', 'a1000000-0000-4000-8000-000000000009', 'a1000000-0000-4000-8000-000000000010', 'a1000000-0000-4000-8000-000000000011', 'a1000000-0000-4000-8000-000000000012')
   or (latitude between 37.85 and 37.9 and longitude between -122.3 and -122.2);

on conflict (id) do update set name = excluded.name, category = excluded.category, price_level = excluded.price_level, cuisine = excluded.cuisine, description = excluded.description, address = excluded.address, neighborhood = excluded.neighborhood, hours = excluded.hours, image_url = excluded.image_url, tags = excluded.tags, latitude = excluded.latitude, longitude = excluded.longitude, source_url = excluded.source_url, is_active = true;
